/**
 * 图片处理 Web Worker
 * 在独立线程中执行 CPU 密集型的图片编码任务
 */

import encodeJpeg from '@jsquash/jpeg/encode';
import encodePng from '@jsquash/png/encode';
import encodeWebp from '@jsquash/webp/encode';
import type {
  WorkerMessage,
  WorkerResponse,
  WorkerResult,
  WorkerTask,
} from './worker-types';

/**
 * Worker 日志（发送到主线程）
 */
function log(message: string) {
  const response: WorkerResponse = {
    type: 'log',
    payload: message,
  };
  self.postMessage(response);
}

/**
 * 执行图片编码任务
 */
async function executeTask(task: WorkerTask): Promise<WorkerResult> {
  const startTime = performance.now();

  try {
    let encodedData: Uint8Array;

    switch (task.type) {
      case 'compress': {
        if (task.sourceFormat === 'jpeg') {
          log(`[Worker] 🗜️  [${task.sizeLabel}] 开始 JPEG 压缩`);
          const result = await encodeJpeg(task.imageData, {
            quality: task.quality,
          });
          encodedData = new Uint8Array(result);
        } else if (task.sourceFormat === 'png') {
          log(`[Worker] 🗜️  [${task.sizeLabel}] 开始 PNG 压缩`);
          const result = await encodePng(task.imageData);
          encodedData = new Uint8Array(result);
        } else {
          throw new Error(`Unsupported source format: ${task.sourceFormat}`);
        }
        break;
      }

      case 'convert-webp': {
        log(`[Worker] 🎨 [${task.sizeLabel}] 开始 WebP 转换`);
        const result = await encodeWebp(task.imageData, {
          quality: task.quality,
        });
        encodedData = new Uint8Array(result);
        break;
      }

      default:
        throw new Error(`Unknown task type: ${(task as any).type}`);
    }

    const processingTime = performance.now() - startTime;
    log(
      `[Worker] ✅ [${task.sizeLabel}] ${task.type} 完成，耗时: ${processingTime.toFixed(0)}ms`
    );

    return {
      id: task.id,
      success: true,
      data: encodedData,
      filename: task.filename,
      processingTime,
    };
  } catch (error) {
    const processingTime = performance.now() - startTime;
    const errorMsg = error instanceof Error ? error.message : '未知错误';

    log(`[Worker] ❌ [${task.sizeLabel}] ${task.type} 失败: ${errorMsg}`);

    return {
      id: task.id,
      success: false,
      error: errorMsg,
      processingTime,
    };
  }
}

/**
 * Worker 消息处理
 */
self.onmessage = async (e: MessageEvent<WorkerMessage>) => {
  const message = e.data;

  if (message.type === 'terminate') {
    log('[Worker] 收到终止信号，正在关闭...');
    self.close();
    return;
  }

  if (message.type === 'task' && message.payload) {
    const task = message.payload;
    const result = await executeTask(task);

    const response: WorkerResponse = {
      type: 'result',
      payload: result,
    };

    // 使用 Transferable Objects 零拷贝传输
    if (result.success && result.data) {
      self.postMessage(response, { transfer: [result.data.buffer] });
    } else {
      self.postMessage(response);
    }
  }
};

// Worker 错误处理
self.onerror = (e) => {
  const response: WorkerResponse = {
    type: 'error',
    payload: `Worker error: ${typeof e === 'string' ? e : (e as ErrorEvent).message}`,
  };
  self.postMessage(response);
};

log('[Worker] 图片处理 Worker 已启动');
